// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Initialize C with some valid addresses to avoid reverts on later calls
        address vader = address(0x1);
        address usdv = address(0x2);
        address vault = address(0x3);
        c.init(vader, usdv, vault);

        // 2. Record proposalCount before the call
        uint256 countBefore = c.proposalCount();

        // 3. Call newGrantProposal with the fuzzed parameters
        vm.prank(address(this));
        c.newGrantProposal(recipient, amount);

        // 4. Record proposalCount after the call
        uint256 countAfter = c.proposalCount();

        // 5. Assert the universal property: proposalCount must have increased by exactly 1.
        //    The reference satisfies this for ALL inputs; the buggy version fails for some (actually all) inputs.
        assertTrue(countAfter == countBefore + 1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
    receive() external payable {}
}

