import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint96 amount) public {
        // 1. ensure recipient is not the zero address
        vm.assume(recipient != address(0));
        // 2. initialize the contract with mock addresses
        c.init(address(0x1), address(0x2), address(0x3));
        // 3. call newGrantProposal with fuzzed inputs
        c.newGrantProposal(recipient, uint256(amount));
        // 4. get the current proposal count
        uint256 pid = c.proposalCount();
        // 5. read the type string for the proposal ID returned by proposalCount
        string memory storedType = c.mapPID_type(pid);
        // 6. assert that the stored type is not empty (i.e., the proposal ID is valid)
        assertTrue(bytes(storedType).length > 0);
    }
}

